__ht__function(json, dm, view, datas) {// ===== 获取 GraphView 和数据模型 =====
var view = graphView.getView();
var dm = graphView.dm();
//滚动条不可见
graphView.setScrollBarVisible(false);

//点位搜集
function createCheckpointRegistry(dm) {

    const list = [];  // 不用Map，改成列表做匹配

    dm.getDatas().each(node => {

        const tag = node.getTag();

        if (!tag || !tag.startsWith('track-')) return;

        const parts = tag.split('-');
        if (parts.length < 3) return;

        const trackId = Number(parts[1]) - 1;

        const shortName = parts.slice(2).join('-'); // XXX

        list.push({
            tag,
            shortName,
            trackId,
            node,
            x: node.getX(),
            y: node.getY()
        });
    });

    return {

        resolve(name) {

            // =========================
            // ✔ 核心：匹配 XXX → track-N-XXX
            // =========================
            const match = list.find(item => item.shortName === name);

            if (!match) {
                console.warn('❌ checkpoint not matched:', name);
                return null;
            }

            return match;
        }
    };
}

//Resolver（检查点解析层）
function createPositionResolver(registry) {

    return {
        resolve(name) {

            const cp = registry.resolve(name);

            if (!cp) return null;

            return {
                trackId: cp.trackId,
                x: cp.x,
                y: cp.y
            };
        }
    };
}

//3. Steel System（区间模型）
function createSteelSystem() {

    const map = new Map();

    return {

        update(id, head, tail) {
            map.set(id, { id, head, tail });
        },

        getAll() {
            return map.values();
        }
    };
}

//4. Track System（N轨动态系统）
function createTrackSystem(dm) {

    return {
        getTracks() {

            const tracks = [];

            dm.getDatas().each(node => {

                const tag = node.getTag();
                if (!tag || !tag.startsWith('track-path-')) return;

                tracks.push({
                    id: tag,
                    node,
                    x: node.getX(),
                    y: node.getPosition().y,
                    width: node.getWidth()
                });
            });

            return tracks;
        }
    };
}

function extractTrackIndex(trackId) {

    const match = trackId.match(/track-path-(\d+)/);

    if (!match) {
        console.warn('❌ invalid track id:', trackId);
        return -1;
    }

    return Number(match[1]) - 1;
}

//5. Projector（区间裁剪层）
function createProjector() {

    return {

    clip(steel, track, trackIndex) {

        const minTrack = Math.min(steel.head.trackId, steel.tail.trackId);
        const maxTrack = Math.max(steel.head.trackId, steel.tail.trackId);

        if (trackIndex < minTrack || trackIndex > maxTrack) return null;

        let start, end;

        if (trackIndex === minTrack) {
            start = steel.tail.x;
            end = 1860;
        }
        else if (trackIndex === maxTrack) {
            start = 60;
            end = steel.head.x;
        }
        else {
            start = 60;
            end = 1860;
        }

        if (start >= end) return null;

        return {
            trackId: track.id,
            y: track.y,
            startX: start,
            endX: end
        };
    }
    };
}

//6. Renderer（UI层）
function createRenderer(dm) {

    const pool = new Map();
    function draw(key, segment) {
        let shape = pool.get(key);
        if (!shape) {
            shape = new ht.Shape();
            shape.setStyle('shape.type', 'polyline');
            shape.setStyle('shape.border.width', 6);
            shape.setStyle('shape.border.color', 'red');
            shape.setStyle('2d.movable', false);
            shape.setLayer(0);
            dm.add(shape);
            console.log(shape)
            pool.set(key, shape);
        }

        shape.setPoints([
            { x: segment.startX, y: segment.y },
            { x: segment.endX, y: segment.y }
        ]);
    }

    function cleanup(activeKeys) {
        pool.forEach((shape, key) => {
            if (!activeKeys.has(key)) {
                dm.remove(shape);
                pool.delete(key);
            }
        });
    }

    return { draw,cleanup };
}

const checkpointRegistry = createCheckpointRegistry(dm);
const resolver = createPositionResolver(checkpointRegistry);
const steelSystem = createSteelSystem();
const trackSystem = createTrackSystem(dm);
const projector = createProjector();
const renderer = createRenderer(dm);


function handleEvent(msg) {

    if (!msg || msg.eventCode !== 'HEADTAIL_HMD') return;

    const d = msg.data;

    const head = resolver.resolve(d.headPosition);
    const tail = resolver.resolve(d.tailPosition);
    console.log(head,tail)

    if (!head || !tail) return;

    steelSystem.update(
        d.slabNo,
        head,
        tail
    );
}

//9. 渲染循环（N轨 + 区间投影）
function loop() {

    const tracks = trackSystem.getTracks();
    const activeKeys = new Set();

    steelSystem.getAll().forEach(steel => {

    const minTrack = Math.min(steel.head.trackId, steel.tail.trackId);
    const maxTrack = Math.max(steel.head.trackId, steel.tail.trackId);

    tracks.forEach(track => {

        const trackIndex = extractTrackIndex(track.id);

        const seg = projector.clip(steel, track, trackIndex);

        if (trackIndex < minTrack || trackIndex > maxTrack) return;

        if (!seg) return;

        const key = steel.id + '@' + track.id;

        activeKeys.add(key);

        renderer.draw(key, seg);
    });
    });
    // ✅ 清理无效 shape
    renderer.cleanup(activeKeys);
    requestAnimationFrame(loop);
}

requestAnimationFrame(loop);

