    // 准备请求数据
const requestData = {
    "line" : Line,
    "Area" : Area,
    "Processes" : Processes,
    "SHIFT_GROUP" : SHIFT_GROUP,
    "ROLL_PLAN_NO": "0",
    "MtlNo": SlabNo.toString(),
