    "RequireValue": parseFloat(RequireValue).toString(), // ✅
    "OccurTime": new Date(OccurTime).toISOString(), // ✅ ISO格式
    "Confirmer": Confirmer.toString()
};

// 发送PUT请求
fetch(url, {
  method: 'PUT', // 指定请求方法为PUT
  headers: {
    'Content-Type': 'application/json', // 指定请求体格式为JSON
  },
  body: JSON.stringify(requestData) // 将JavaScript对象转换为JSON字符串
})
.then(response => {
